const config=window.MMM||{images:{},email:'',whatsapp:''};
const path=location.pathname.replace(/\/$/,'')||'/';
const main=document.querySelector('main');
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const routeNames={'/':'Create. Build. Grow.','/work':'Selected Work','/video-photo':'Video + Photography','/web-development':'Web Development','/business-growth':'Business Growth','/about':'About the Studio','/contact':'Get a Quote'};
document.title=`${routeNames[path]||'Page not found'} — MegMultiMedia`;
const menu=document.querySelector('.menu');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close menu':'Open menu');document.querySelector('nav').classList.toggle('open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.setAttribute('aria-expanded','false');document.querySelector('nav').classList.remove('open')}});
document.querySelectorAll('nav a').forEach(a=>{if(a.getAttribute('href')===path)a.setAttribute('aria-current','page')});
const arrow='↗';
const link=(href,label,kind='text-link')=>`<a class="${kind}" href="${href}">${label} <span>${arrow}</span></a>`;
const tag=(n,text)=>`<div class="section-tag"><span>${n} / ${text}</span><span class="cross">✳</span></div>`;
const stockNote='<span class="stock-label">STOCK IMAGERY · ILLUSTRATIVE</span>';
const photo=(key,alt,extra='')=>`<img src="${config.images[key]}" alt="${alt}" loading="lazy" ${extra}>`;
const ticker=`<div class="ticker" aria-label="Ideas into impact"><div aria-hidden="true">IDEAS INTO IMPACT <span>✳</span> CREATE DIFFERENTLY <span>✳</span> IDEAS INTO IMPACT <span>✳</span> CREATE DIFFERENTLY <span>✳</span></div></div>`;
const cta=(title="LET’S CREATE SOMETHING<br><i>WORTH REMEMBERING.</i>")=>`<section class="cta"><div class="section-tag"><span>YOUR NEXT MOVE</span><span>LET’S MAKE IT MATTER.</span></div><h2>${title}</h2><div class="cta-bottom"><p>Have a brand, campaign<br>or project in mind?</p><div>${link('/contact','GET A QUOTE','button dark')}${config.whatsapp?`<a class="button outline" href="https://wa.me/${config.whatsapp.replace(/\D/g,'')}?text=${encodeURIComponent('Hi MegMultiMedia, I’d like to discuss a project for my brand.')}" target="_blank" rel="noopener">WHATSAPP US ↗</a>`:''}</div></div></section>`;
const title=(eyebrow,heading,description='')=>`<section class="page-heading"><span class="eyebrow">${eyebrow}</span><h1>${heading}</h1>${description?`<p>${description}</p>`:''}</section>`;
const projectCard=(key,name,category,n,wide=false)=>`<button class="project ${wide?'wide':''}" data-project="${key}" aria-label="View ${name} illustrative photograph"><div class="project-image">${photo(key,name+' — illustrative stock photograph')}${stockNote}<span class="view-project">VIEW<br>IMAGE ↗</span><span class="project-no">${n}</span></div><div class="project-caption"><h3>${name}</h3><span>${category} ↗</span></div></button>`;
const work=(full=false)=>`<section class="section work-section" id="selected-work">${tag('01','THE VISUAL EDIT')}<div class="section-heading"><h2>MADE TO<br><i>MAKE YOU LOOK.</i></h2><p>Production. Photography. Digital.<br>A feel for what comes next.</p></div><p class="editorial-note">A visual direction preview using stock imagery. Client projects will replace these images.</p><div class="project-grid">${projectCard('product','Objects of attention','PRODUCT / VISUAL DIRECTION','01',true)}${projectCard('food','A taste of something different','FOOD & DRINK / PHOTOGRAPHY','02')}${full?projectCard('production','Behind every frame','PRODUCTION / ON SET','03'):''}</div>${!full?link('/work','EXPLORE THE VISUAL EDIT'):''}</section>`;
const serviceData=[['CREATIVE','The idea comes first.',['Scriptwriting','Creative Direction','Content Strategy'],'We find the story, shape the concept, and give every piece of content a clear purpose.'],['PRODUCTION','Bring it into focus.',['Videography','Photography','Video Production','Video Editing'],'From the first frame to the final cut, every detail works together to tell your story.'],['DIGITAL','Built for the way people move.',['Social Media Management','Website Development','SEO'],'Digital experiences that connect your brand to people, across screens and platforms.'],['GROWTH','Make attention mean something.',['Influencer Marketing','Meta Ads','Google Ads','Performance Marketing','PR & Press Releases'],'Connect creative thinking with distribution, testing, and measurement.']];
const services=()=>`<section class="section capabilities">${tag('02','WHAT WE CREATE')}<div class="service-list">${serviceData.map((s,i)=>`<details ${i===0?'open':''}><summary><span class="service-index">0${i+1}</span><h3>${s[0]}</h3><span class="plus">+</span></summary><div class="service-content"><p>${s[1]}<br><span>${s[3]}</span></p><ul>${s[2].map(x=>`<li>${x}</li>`).join('')}</ul></div></details>`).join('')}</div></section>`;
const growthServices=[['Influencer marketing','Creator collaborations, UGC, outreach and campaign amplification.'],['Meta ads','Audience targeting, lead generation, retargeting and creative testing.'],['Google ads','Search, YouTube and display campaigns shaped around your goals.'],['SEO','Technical, on-page, local and content SEO for discoverability.'],['Social media','Content planning, publishing, community and analytics.'],['PR & press releases','Brand announcements, digital PR and media outreach.']];
const dashboard=()=>`<div class="growth-console"><div class="console-top"><span>MMM / GROWTH FRAMEWORK</span><span>01 — 05</span></div><div class="growth-steps" role="tablist" aria-label="Growth stages">${['Creativity','Attention','Audience','Performance','Growth'].map((x,i)=>`<button role="tab" id="stage-${i}" aria-selected="${i===0}" tabindex="${i===0?0:-1}" aria-controls="stage-panel" data-stage="${i}">${x}</button>`).join('')}</div><div id="stage-panel" role="tabpanel" aria-labelledby="stage-0" tabindex="0"><span class="stage-counter">01</span><h3 id="stage-title">START WITH<br>A STRONG IDEA.</h3><p id="stage-copy">Make something people want to stop for.</p><div class="signal" aria-hidden="true">${Array.from({length:24},(_,i)=>`<span style="--h:${20+((i*17)%65)}%;--delay:${i*.06}s"></span>`).join('')}</div></div><div class="metrics">${['REACH','ENGAGEMENT','LEADS','CTR','CPL','CONVERSIONS','ROAS','RETENTION'].map(x=>`<span>${x}<b>—</b></span>`).join('')}</div><p class="console-note">THE METRICS WE WORK WITH. NO SIMULATED RESULTS.</p></div>`;
const growth=(full=false)=>`<section class="section growth-section">${tag('03','CREATIVE MEETS COMMERCIAL')}<div class="growth-layout"><div><h2>CREATIVITY GETS<br><i>ATTENTION.</i><br>GROWTH TURNS IT<br>INTO <em>BUSINESS.</em></h2><p>Make the content. Build the audience.<br>Measure what matters.</p>${!full?link('/business-growth','EXPLORE BUSINESS GROWTH'):''}</div>${dashboard()}</div>${full?`<div class="growth-offerings">${growthServices.map((s,i)=>`<article><span>0${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p></article>`).join('')}</div>`:''}</section>`;
const bts=()=>`<section class="section bts">${tag('04','BEHIND THE CONTENT')}<div class="bts-grid"><div class="bts-photo">${photo('production','Cinema camera on a production set — illustrative stock imagery')}${stockNote}<span class="frame-corner"></span></div><div class="bts-copy"><span class="eyebrow">THE PROCESS IS PART OF THE STORY.</span><h2>BEFORE<br>THE <i>FINAL CUT.</i></h2><p>Ideas become setups. Setups become stories. A look at the craft behind the content.</p><div class="process"><span>01 / SETUP</span><span>02 / SHOOT</span><span>03 / EDIT</span><span>04 / FINAL</span></div>${link('/video-photo','EXPLORE PRODUCTION')}</div></div></section>`;
const browser=()=>`<div class="browser-object"><div class="browser-bar"><span class="browser-dots">● ● ●</span><span>MMM / DIGITAL CONCEPT</span><span>↗</span></div><div class="browser-preview" tabindex="0" aria-label="Scrollable MMM website concept"><div class="concept-nav">MMM® <span>IDEAS WITHOUT LIMITS.</span></div><h3>MAKE<br><i>YOUR<br>MARK.</i></h3><span class="concept-disc">CREATE<br>SOMETHING<br>DIFFERENT ↗</span><div class="concept-below"><h4>A FIRST IMPRESSION.<br>A LASTING CONNECTION.</h4><p>Strategy → Design → Development → Launch</p></div></div><div class="browser-foot">IN-HOUSE DESIGN EXPLORATION <span>SCROLL INSIDE ↓</span></div></div>`;
const digital=(full=false)=>`<section class="section digital">${tag('05','DIGITAL EXPERIENCES')}<div class="digital-layout"><div><h2>GOOD LOOKS.<br><i>GREAT<br>EXPERIENCES.</i></h2><p>We build digital experiences too.<br>Thoughtfully designed. Built to move.</p>${!full?link('/web-development','EXPLORE WEB DEVELOPMENT'):''}</div>${browser()}</div>${full?`<div class="approach-line">${['DESIGN','DEVELOPMENT','MOBILE','SEO','LAUNCH'].map((x,i)=>`<span><small>0${i+1}</small>${x}</span>`).join('')}</div><p class="editorial-note">The interactive preview is an MMM design concept. Verified client websites will be added here.</p>`:''}</section>`;
const about=()=>`<section class="section about-strip">${tag('06','MEET MEGMULTIMEDIA')}<div class="about-grid"><h2>MORE THAN<br><i>MARKETING.</i></h2><div><p class="large-copy">A creative and digital agency bringing content production, digital experiences and business growth under one roof.</p>${link('/about','MEET THE STUDIO')}</div></div></section>`;
if(path==='/'){main.insertAdjacentHTML('beforeend',ticker+work()+services()+growth()+bts()+digital()+about()+cta())}
else if(path==='/work'){main.innerHTML=title('THE MMM PORTFOLIO','WORK.<br><i>IN EVERY FORM.</i>','A visual exploration of production, photography and digital experiences.')+work(true)+digital()+cta()}
else if(path==='/video-photo'){main.innerHTML=title('PRODUCTION / PHOTOGRAPHY / CONTENT','EVERY FRAME.<br><i>A FEELING.</i>','Video. Photography. Content. From the idea to the final cut.')+`<section class="section production-gallery"><div class="section-heading"><h2>THE <i>VISUAL EDIT.</i></h2><span class="eyebrow">SWIPE / SCROLL TO EXPLORE</span></div><p class="editorial-note">Illustrative stock photography. Original client films and BTS will follow.</p><div class="horizontal-gallery">${projectCard('food','In good taste','FOOD & DRINK','01')}${projectCard('product','An eye for detail','PRODUCT','02')}${projectCard('production','The making of','PRODUCTION','03')}</div></section>`+bts()+`<section class="section equipment">${tag('THE TOOLKIT','BUILT FOR THE SHOT')}<div>${['SONY α7R V','GM LENSES','LUMIX S1H','GODOX LIGHTING','GIMBALS','TRIPODS'].map(x=>`<span>${x}</span>`).join('')}</div></section>`+cta('NEED CONTENT<br><i>FOR YOUR BRAND?</i>')}
else if(path==='/web-development'){main.innerHTML=title('DESIGN / DEVELOPMENT / EXPERIENCE','WE BUILD<br><i>DIGITAL EXPERIENCES.</i>','Websites with a point of view. Experiences with a purpose.')+digital(true)+cta('YOUR NEXT WEBSITE<br><i>STARTS HERE.</i>')}
else if(path==='/business-growth'){main.innerHTML=title('STRATEGY / DISTRIBUTION / PERFORMANCE','CREATIVE IS ONLY<br><i>THE BEGINNING.</i>','We turn content, audiences and digital platforms into measurable growth opportunities.')+growth(true)+`<section class="section growth-manifesto"><h2>MAKE THE CONTENT.<br><i>BUILD THE AUDIENCE.</i><br>MEASURE THE GROWTH.</h2></section>`+cta()}
else if(path==='/about'){main.innerHTML=title('THE STUDIO / MEGMULTIMEDIA','MANY DISCIPLINES.<br><i>ONE CREATIVE MINDSET.</i>')+`<section class="section about-page"><div class="about-grid"><div class="about-logo"><img src="/assets/mmm-logo.jpg" alt="MMM logo"></div><div><span class="eyebrow">OUR STORY</span><p class="large-copy">MegMultiMedia brings content production, digital experiences and business growth under one roof.</p><p>Creative thinking and practical execution, connected from the first idea to the final experience.</p></div></div><div class="approach-line">${['STRATEGY','CREATE','DISTRIBUTE','OPTIMIZE'].map((x,i)=>`<span><small>0${i+1}</small>${x}</span>`).join('')}</div><div class="founder"><span class="eyebrow">THE PERSON BEHIND MEGMULTIMEDIA</span><h2>RITHWIK<br><i>PEMMADA.</i></h2><p>Managing Director</p></div></section>`+cta()}
else if(path==='/contact'){main.innerHTML=title('LET’S MAKE SOMETHING HAPPEN','HAVE A PROJECT<br><i>IN MIND?</i>')+`<section class="section contact-layout"><div><p class="large-copy">A fresh idea.<br>A bold campaign.<br>Your next chapter.</p><p>Tell us what you’re thinking.</p><div class="contact-note"><b>ENQUIRY PREVIEW</b><p>Contact details are being added. You can prepare and download your project brief below. Nothing is sent from this preview.</p></div></div><form id="enquiry"><div class="form-row"><label>Your name<input name="name" autocomplete="name" required placeholder="Full name"></label><label>Business name<input name="business" autocomplete="organization" placeholder="Your brand or business"></label></div><div class="form-row"><label>Email<input name="email" type="email" autocomplete="email" required placeholder="you@company.com"></label><label>Phone<input name="phone" type="tel" autocomplete="tel" placeholder="Include country code"></label></div><fieldset><legend>What can we help with?</legend><div class="service-choices">${['Creative','Video & Photography','Website Development','Social Media','Business Growth','Other'].map(x=>`<label><input type="checkbox" name="services" value="${x}"><span>${x}</span></label>`).join('')}</div></fieldset><label>Project details<textarea name="details" rows="4" required placeholder="A little about your idea, goals and timeline…"></textarea></label><button class="button" type="submit">PREPARE PROJECT BRIEF <span>↗</span></button><p class="form-privacy">Your details stay in this browser. They are not saved or submitted.</p><div id="form-result" aria-live="polite"></div></form></section>`}
else{main.innerHTML=title('404','THIS WAY<br><i>BACK TO CREATIVE.</i>')+`<section class="section">${link('/','BACK TO HOME','button')}</section>`}
// Navigation transitions retain an immediate fallback for browsers without View Transitions.
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||a.target||e.metaKey||e.ctrlKey||e.shiftKey||a.origin!==location.origin)return;if(a.pathname===location.pathname&&a.hash)return;document.body.classList.add('leaving')});
const stageTexts=[['START WITH<br>A STRONG IDEA.','Make something people want to stop for.'],['EARN THE<br>SECOND LOOK.','Bring the right creative to the right places.'],['FIND YOUR<br>PEOPLE.','Connect your message with an audience that matters.'],['TEST. LEARN.<br>REFINE.','Use meaningful metrics to inform the next move.'],['BUILD ON<br>WHAT WORKS.','Turn learning into a repeatable growth strategy.']];
function setStage(button){const n=Number(button.dataset.stage);document.querySelectorAll('[data-stage]').forEach(b=>{b.setAttribute('aria-selected',b===button);b.tabIndex=b===button?0:-1});document.querySelector('#stage-panel').setAttribute('aria-labelledby',button.id);document.querySelector('#stage-title').innerHTML=stageTexts[n][0];document.querySelector('#stage-copy').textContent=stageTexts[n][1];document.querySelector('.stage-counter').textContent=`0${n+1}`;document.querySelector('.growth-console').style.setProperty('--stage',n);}
document.querySelectorAll('[data-stage]').forEach(b=>{b.addEventListener('click',()=>setStage(b));b.addEventListener('keydown',e=>{const tabs=[...document.querySelectorAll('[data-stage]')];let i=tabs.indexOf(b);if(e.key==='ArrowRight')i=(i+1)%tabs.length;else if(e.key==='ArrowLeft')i=(i-1+tabs.length)%tabs.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=tabs.length-1;else return;e.preventDefault();tabs[i].focus();setStage(tabs[i])})});
const dialog=document.createElement('dialog');dialog.className='lightbox';dialog.innerHTML='<button class="close-dialog" aria-label="Close image">×</button><img alt=""><p></p>';document.body.append(dialog);let lastProject;
document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{lastProject=b;dialog.querySelector('img').src=config.images[b.dataset.project];dialog.querySelector('img').alt=b.querySelector('img').alt;dialog.querySelector('p').textContent=b.querySelector('h3').textContent+' — illustrative stock photography';dialog.showModal()}));
function closeDialog(){dialog.close();lastProject?.focus()}dialog.querySelector('button').addEventListener('click',closeDialog);dialog.addEventListener('click',e=>{if(e.target===dialog)closeDialog()});
const form=document.querySelector('#enquiry');if(form)form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form);const brief=`MEGMULTIMEDIA — PROJECT ENQUIRY\n\nName: ${d.get('name')}\nBusiness: ${d.get('business')}\nEmail: ${d.get('email')}\nPhone: ${d.get('phone')}\nServices: ${d.getAll('services').join(', ')||'To discuss'}\n\nPROJECT DETAILS\n${d.get('details')}\n`;const result=document.querySelector('#form-result');result.replaceChildren();const p=document.createElement('p');p.textContent='Your brief is ready. Download it to keep a copy. Nothing has been sent.';const download=document.createElement('a');download.className='button';download.textContent='DOWNLOAD BRIEF ↓';download.download='MMM-project-enquiry.txt';const url=URL.createObjectURL(new Blob([brief],{type:'text/plain'}));download.href=url;result.append(p,download);download.focus()});
if(!reduced){const observer=new IntersectionObserver(entries=>entries.forEach(x=>{if(x.isIntersecting){x.target.classList.add('visible');observer.unobserve(x.target)}}),{threshold:.08});document.querySelectorAll('.section-heading,.growth-layout,.bts-grid,.digital-layout,.about-grid,.founder,.project').forEach(el=>{el.classList.add('reveal');observer.observe(el)});if(matchMedia('(pointer:fine)').matches){document.querySelectorAll('.project,.browser-object,.logo-world').forEach(el=>{el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;const target=el.classList.contains('logo-world')?el.querySelector('img'):el;target.style.transform=`perspective(1000px) rotateX(${-y*5}deg) rotateY(${x*8}deg)${el.classList.contains('logo-world')?' rotate(-9deg)':''}`});el.addEventListener('pointerleave',()=>{(el.classList.contains('logo-world')?el.querySelector('img'):el).style.transform=''})})}}
// A quiet WebGL wireframe field echoes the logo's dimensional geometry.
if(path==='/'&&!reduced){const canvas=document.createElement('canvas');canvas.className='hero-canvas';canvas.setAttribute('aria-hidden','true');document.querySelector('.hero').prepend(canvas);const gl=canvas.getContext('webgl',{alpha:true,antialias:true});if(gl){const vertex='attribute vec2 p;uniform vec2 shift;void main(){gl_Position=vec4(p+shift,0.0,1.0);}';const fragment='precision mediump float;void main(){gl_FragColor=vec4(.25,.58,.37,.21);}';function shader(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);return s}const program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,vertex));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,fragment));gl.linkProgram(program);gl.useProgram(program);const vertices=new Float32Array([.24,-.5,.76,-.43,.86,.43,.34,.36,.24,-.5,.3,-.56,.82,-.49,.76,-.43,.82,-.49,.92,.37,.86,.43,.92,.37,.4,.3,.34,.36,.4,.3,.3,-.56]);const buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,vertices,gl.STATIC_DRAW);const position=gl.getAttribLocation(program,'p');gl.enableVertexAttribArray(position);gl.vertexAttribPointer(position,2,gl.FLOAT,false,0,0);const shift=gl.getUniformLocation(program,'shift');const render=(x=0,y=0)=>{const r=canvas.getBoundingClientRect();canvas.width=r.width*devicePixelRatio;canvas.height=r.height*devicePixelRatio;gl.viewport(0,0,canvas.width,canvas.height);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);gl.uniform2f(shift,x,y);gl.drawArrays(gl.LINE_STRIP,0,vertices.length/2)};render();window.addEventListener('resize',()=>render());document.querySelector('.hero').addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();render((e.clientX/r.width-.5)*.03,-(e.clientY/r.height-.5)*.03)})}}
